-- DPS Enhanced: ox_inventory item list.
--
-- This file replaces the stock data/items.lua. It builds the list from two files next to it:
--   items_legacy.lua  the old DPS server's item list, unchanged
--   items_dps.lua     the rules: which of those load (keep), wait (hold) or are retired (drop)
-- To change what loads, edit items_dps.lua. Do not edit this file or items_legacy.lua.

local legacy = lib.load('data.items_legacy') or {}
local rules = lib.load('data.items_dps') or {}

---@param list string[]?
---@return table<string, true>
local function toSet(list)
    local set = {}
    for i = 1, #(list or {}) do set[list[i]] = true end
    return set
end

---@param name string
---@param patterns string[]?
---@return boolean
local function matchesAny(name, patterns)
    for i = 1, #(patterns or {}) do
        if name:find(patterns[i]) then return true end
    end
    return false
end

---The resource an item's use is wired to, if any: `export = 'resource.function'`.
---@param item table
---@return string?
local function exportResource(item)
    local export = item.export
        or (type(item.client) == 'table' and item.client.export)
        or (type(item.server) == 'table' and item.server.export)

    return type(export) == 'string' and export:match('^(.-)%.') or nil
end

local keep = rules.keep or {}
local drop = rules.drop or {}
local hold = rules.hold or {}
local dropNames, holdNames = toSet(drop.names), toSet(hold.names)

---@param name string
---@param item table
---@return 'keep' | 'hold' | 'drop'
local function verdict(name, item)
    if keep[name] then return 'keep' end

    if dropNames[name] or matchesAny(name, drop.patterns) then return 'drop' end
    if drop.categories and drop.categories[item.category] then return 'drop' end

    if holdNames[name] or matchesAny(name, hold.patterns) then return 'hold' end

    local description = item.description
    if type(description) == 'string' then
        for i = 1, #(hold.descriptions or {}) do
            if description:sub(1, #hold.descriptions[i]) == hold.descriptions[i] then return 'hold' end
        end
        if hold.unlabelledParts and description == name and item.label == name then return 'hold' end
    end

    -- Wired to a script that is not on this server: wait for it. 'missing' and not 'stopped',
    -- because resources that start after ox_inventory are not running yet when this file loads.
    local resource = exportResource(item)
    if resource and GetResourceState(resource) == 'missing' then return 'hold' end

    return 'keep'
end

local items = {}
local count = { keep = 0, hold = 0, drop = 0 }

for name, item in pairs(legacy) do
    local result = verdict(name, item)
    count[result] += 1
    if result == 'keep' then items[name] = item end
end

local added = 0
for name, item in pairs(rules.add or {}) do
    if not items[name] then added += 1 end
    items[name] = item
end

if IsDuplicityVersion() then
    print(('[dps] items: %d from the DPS list, %d new, %d held, %d dropped'):format(count.keep, added, count.hold, count.drop))
end

return items
